    internal static class LocalizedText
    {
        public static string Get(string key)
        {
            return ModLocalization.Service.Get(key);
        }

        public static string Format(string key, params object[] args)
        {
            return ModLocalization.Service.Format(key, args);
        }

        public static string GetOrDefault(string key, string defaultText)
        {
            var localized = Get(key);
            return string.Equals(localized, key, StringComparison.Ordinal)
                ? defaultText
                : localized;
        }

        public static string FormatOrDefault(string key, string defaultFormat, params object[] args)
        {
            var format = GetOrDefault(key, defaultFormat);
            return args == null || args.Length == 0
                ? format
                : string.Format(format, args);
        }
    }

