            Add(translations,  ModTextKey.TabletAnalyticsCommodityTrendDescription,  "Shows commodity price trends for the selected timeframe. Only includes completed contracts.",  "Affiche les tendances de prix des marchandises pour la période sélectionnée. N'inclut que les contrats terminés.",  "Mostra le tendenze dei prezzi delle merci per il periodo selezionato. Include solo i contratti completati.",  "Muestra las tendencias de precios de las mercancías para el período seleccionado. Solo incluye contratos completados.",  "Показывает тенденции цен на товары для выбранного периода. Включает только завершенные контракты.",  "Mostra as tendências de preços das mercadorias para o período selecionado. Inclui apenas contratos concluídos.",  "Seçilen zaman dilimi için emtia fiyat eğilimlerini gösterir. Yalnızca tamamlanmış sözleşmeleri içerir.");
            Add(translations,  ModTextKey.TabletAnalyticsSiteUtilization,  "Site utilization",  "Utilisation du site",  "Utilizzo del sito",  "Utilización del sitio",  "Использование площадки",  "Utilização do site",  "Site kullanımı");
            Add(translations,  ModTextKey.TabletAnalyticsSiteUtilizationDescription,  "Shows the percentage of available site slots that are occupied over time. Only includes completed contracts.",  "Affiche le pourcentage de créneaux de site disponibles qui sont occupés au fil du temps. N'inclut que les contrats terminés.",  "Mostra la percentuale di slot del sito disponibili che sono occupati nel tempo. Include solo i contratti completati.",  "Muestra el porcentaje de ranuras de sitio disponibles que están ocupadas a lo largo del tiempo. Solo incluye contratos completados.",  "Показывает процент доступных слотов площадки, которые заняты со временем. Включает только завершенные контракты.",  "Mostra a porcentagem de slots de site disponíveis que estão ocupados ao longo do tempo. Inclui apenas contratos concluídos.",  "Zaman içinde dolu olan mevcut site yuvalarının yüzdesini gösterir. Yalnızca tamamlanmış sözleşmeleri içerir.");
            Add(translations,  ModTextKey.TabletAnalyticsStorageFill,  "Storage fill",  "Remplissage de stockage",  "Riempimento magazzino",  "Llenado de almacenamiento",  "Заполнение склада",  "Preenchimento de armazenamento",  "Depolama doluluk");
            Add(translations,  ModTextKey.TabletAnalyticsStorageFillDescription,  "Shows the percentage of available storage slots that are occupied over time. Only includes completed contracts.",  "Affiche le pourcentage de créneaux de stockage disponibles qui sont occupés au fil du temps. N'inclut que les contrats terminés.",  "Mostra la percentuale di slot di stoccaggio disponibili che sono occupati nel tempo. Include solo i contratti completati.",  "Muestra el porcentaje de ranuras de almacenamiento disponibles que están ocupadas a lo largo del tiempo. Solo incluye contratos completados.",  "Показывает процент доступных слотов хранения, которые заняты со временем. Включает только завершенные контракты.",  "Mostra a porcentagem de slots de armazenamento disponíveis que estão ocupados ao longo do tempo. Inclui apenas contratos concluídos.",  "Zaman içinde dolu olan mevcut depolama yuvalarının yüzdesini gösterir. Yalnızca tamamlanmış sözleşmeleri içerir.");
            Add(translations,  ModTextKey.TabletAnalyticsDistrictInfluence,  "District influence",  "Influence de district",  "Influenza del distretto",  "Influencia del distrito",  "Влияние района",  "Influência do distrito",  "Bölge etkisi");
